// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const app = express();

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0'; // Listen on all interfaces by default

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    service: process.env.SERVICE_NAME || 'user-service'
  });
});

app.get('/users', (req, res) => {
  // In a real app, this would come from a database
  // For demo, we can optionally override via env vars for testing
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Allow override for testing via environment variable (JSON string)
  if (process.env.TEST_USERS) {
    try {
      const parsedUsers = JSON.parse(process.env.TEST_USERS);
      if (Array.isArray(parsedUsers)) {
        return res.json(parsedUsers);
      }
    } catch (e) {
      // If parsing fails, use default users
      console.warn('Failed to parse TEST_USERS env var, using defaults');
    }
  }

  res.json(users);
});

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
});

// For testing purposes
if (process.env.NODE_ENV !== 'test') {
  module.exports = app;
} else {
  module.exports = { app, server };
}

